		layer_2_out[i] = ReLU(result);
	}

	// Layer 3
/*L10:*/	for(int i=0; i<M3; i++)
#pragma HLS pipeline II=auto{_PIPE_L10}
#pragma HLS unroll factor=auto{_UNROLL_L10}
	{
		l_quantized_type result = 0;
/*L11:*/	for(int j=0; j<N3; j++)
#pragma HLS pipeline II=auto{_PIPE_L11}
#pragma HLS unroll factor=auto{_UNROLL_L11}
		{
			l_quantized_type term = layer_2_out[j] * W3[j][i];
			result += term;
		}
		y[i] = tanh(result).to_float();
	}
}
